:root {
  --bg: #f7f8fa; --card: #ffffff; --ink: #1c2230; --muted: #6b7385;
  --line: #e4e7ee; --accent: #2f6df6; --accent-soft: #eaf1ff;
}
* { box-sizing: border-box; }
body { margin: 0; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background: var(--bg); color: var(--ink); line-height: 1.5; }
header { background: var(--card); border-bottom: 1px solid var(--line);
  padding: 18px 28px; display: flex; align-items: center; gap: 12px; }
header h1 { font-size: 18px; margin: 0; font-weight: 650; }
header .tag { font-size: 12px; color: var(--muted); background: var(--bg);
  padding: 3px 9px; border-radius: 20px; border: 1px solid var(--line); }
header .variant { font-size: 12px; color: var(--accent); background: var(--accent-soft);
  padding: 3px 10px; border-radius: 20px; font-weight: 600; }
main { max-width: 760px; margin: 0 auto; padding: 28px; }
.count { font-size: 13px; color: var(--muted); margin: 0 0 12px 2px; }
ul.library { list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 12px; }
li.item { background: var(--card); border: 1px solid var(--line); border-radius: 12px;
  padding: 16px 18px; display: flex; gap: 14px; align-items: flex-start; position: relative; }
.favicon { width: 38px; height: 38px; border-radius: 9px; background: var(--accent-soft);
  display: flex; align-items: center; justify-content: center; font-size: 17px;
  color: var(--accent); flex-shrink: 0; font-weight: 700; }
.item .body { flex: 1; min-width: 0; }
.item a.title { font-weight: 650; font-size: 16px; margin: 0 0 3px; display: inline-block;
  color: var(--ink); text-decoration: none; }
.item a.title:hover { color: var(--accent); text-decoration: underline; }
.item .desc { font-size: 14px; color: #444b5c; margin: 2px 0 8px;
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.item .tags { display: flex; gap: 6px; flex-wrap: wrap; margin-bottom: 8px; align-items: center; }
.chip { font-size: 12px; color: var(--accent); background: var(--accent-soft);
  padding: 3px 10px; border-radius: 20px; display: inline-flex; align-items: center; gap: 5px; }
.chip .x { cursor: pointer; color: var(--muted); font-weight: 700; }
.chip .x:hover { color: #d23; }
.addtag { font-size: 12px; color: var(--muted); background: var(--bg);
  padding: 3px 10px; border-radius: 20px; border: 1px dashed var(--line); cursor: pointer; }
.addtag:hover { color: var(--accent); border-color: var(--accent); }
.item .meta { font-size: 12px; color: var(--muted); display: flex; gap: 10px; }
.item .meta a { color: var(--muted); text-decoration: none; }
.item .meta a:hover { text-decoration: underline; }
.taginput { font-size: 12px; padding: 3px 8px; border: 1px solid var(--accent);
  border-radius: 20px; outline: none; width: 130px; }
/* popover (variant B) */
.pop { position: absolute; z-index: 5; background: var(--card); border: 1px solid var(--line);
  border-radius: 12px; box-shadow: 0 8px 24px rgba(20,30,60,.14); padding: 12px; width: 240px; }
.pop .lbl { font-size: 11px; color: var(--muted); text-transform: uppercase;
  letter-spacing: .04em; margin: 0 0 8px; }
.pop .picklist { display: flex; gap: 6px; flex-wrap: wrap; margin-bottom: 10px; }
.pop .pick { font-size: 12px; padding: 3px 10px; border-radius: 20px; cursor: pointer;
  border: 1px solid var(--line); background: var(--bg); color: var(--ink); }
.pop .pick.on { background: var(--accent); color: #fff; border-color: var(--accent); }
.pop input { width: 100%; font-size: 13px; padding: 7px 9px; border: 1px solid var(--line);
  border-radius: 8px; outline: none; }
.pop input:focus { border-color: var(--accent); }
/* details panel (variant C) */
.panel { position: fixed; top: 0; right: 0; height: 100%; width: 380px; background: var(--card);
  border-left: 1px solid var(--line); box-shadow: -8px 0 24px rgba(20,30,60,.1);
  padding: 24px; transform: translateX(100%); transition: transform .22s ease; z-index: 10; }
.panel.open { transform: none; }
.panel h2 { font-size: 16px; margin: 0 0 4px; }
.panel .psite { font-size: 12px; color: var(--muted); margin-bottom: 20px; }
.panel .lbl { font-size: 12px; font-weight: 600; color: var(--muted); margin: 16px 0 8px; }
.panel .close { position: absolute; top: 16px; right: 18px; cursor: pointer; color: var(--muted);
  font-size: 20px; background: none; border: none; }
.panel input.tagfield { width: 100%; font-size: 14px; padding: 9px 11px; border: 1px solid var(--line);
  border-radius: 9px; outline: none; }
.panel input.tagfield:focus { border-color: var(--accent); }
.opencard { cursor: pointer; }
.hint { font-size: 12px; color: var(--muted); margin-top: 6px; }
</content>

