function timeNow(){return new Date().toLocaleString(undefined,{month:"short",day:"numeric",hour:"numeric",minute:"2-digit"});}
// Minimal Markdown renderer for note previews (bold, italic, code, links, headings, lists).
function mdToHtml(src){
  let s=src.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");
  const lines=s.split(/\n/); let out=[], inList=false;
  for(let ln of lines){
    let m;
    if(m=ln.match(/^\s*[-*]\s+(.*)$/)){ if(!inList){out.push("<ul>");inList=true;} out.push("<li>"+inline(m[1])+"</li>"); continue; }
    if(inList){out.push("</ul>");inList=false;}
    if(m=ln.match(/^\s*(#{1,3})\s+(.*)$/)){ const h=m[1].length; out.push("<h"+h+">"+inline(m[2])+"</h"+h+">"); continue; }
    if(ln.trim()==="") continue;
    out.push("<p>"+inline(ln)+"</p>");
  }
  if(inList)out.push("</ul>");
  return out.join("");
  function inline(t){
    return t
      .replace(/`([^`]+)`/g,"<code>$1</code>")
      .replace(/\[([^\]]+)\]\((https?:[^)]+)\)/g,'<a href="$2" target="_blank" rel="noopener">$1</a>')
      .replace(/\*\*([^*]+)\*\*/g,"<strong>$1</strong>")
      .replace(/\*([^*]+)\*/g,"<em>$1</em>");
  }
}

