// Preserved copy viewer — shows the snapshot captured when the link was saved.
function openSnapshot(id){
  const it = items.find(x=>x.id===id);
  document.getElementById("snapCap").textContent = "Preserved copy · captured " + (it.capturedAt || it.saved);
  document.getElementById("snapUrl").textContent = it.url;
  document.getElementById("snapBody").innerHTML =
    "<h1>"+it.title+"</h1>"+
    "<p><em>"+it.desc+"</em></p>"+
    "<p>"+it.desc+" This is the text of the page as it existed when you saved it. "+
    "Even if the original page later changes or goes offline, this preserved copy stays in your library.</p>"+
    "<p>The full article content captured from <strong>"+it.host+"</strong> would appear here.</p>";
  document.getElementById("overlay").classList.add("open");
}
document.getElementById("snapClose").addEventListener("click",()=>document.getElementById("overlay").classList.remove("open"));
document.getElementById("overlay").addEventListener("click",e=>{if(e.target.id==="overlay")e.target.classList.remove("open");});

