function isPdf(url){ return /\.pdf($|[?#])/i.test(url); }
// Preserved copy viewer — shows the snapshot captured when the link was saved.
function openSnapshot(id){
  const it = items.find(x=>x.id===id);
  const pdf = isPdf(it.url);
  document.getElementById("snapCap").textContent =
    (pdf ? "Preserved PDF" : "Preserved copy") + " · captured " + (it.capturedAt || it.saved);
  document.getElementById("snapUrl").textContent = it.url;
  if (pdf) {
    document.getElementById("snapBody").innerHTML =
      '<div style="border:1px solid #e4e7ee;border-radius:10px;padding:28px;text-align:center;background:#fafbfc">'+
      '<div style="font-size:40px">📕</div>'+
      '<h1 style="justify-content:center">'+it.title+'</h1>'+
      '<p>The <strong>original PDF file</strong> is preserved exactly as it was, page for page — not converted into a reader page.</p>'+
      '<p style="color:#6b7385;font-size:13px">In the real app the stored PDF would open here for reading or download.</p>'+
      '</div>';
  } else {
    document.getElementById("snapBody").innerHTML =
      "<h1>"+it.title+"</h1>"+
      "<p><em>"+it.desc+"</em></p>"+
      "<p>"+it.desc+" This is the readable text of the page as it existed when you saved it. "+
      "Even if the original page later changes or goes offline, this preserved copy stays in your library.</p>"+
      "<p>The full article content captured from <strong>"+it.host+"</strong> would appear here.</p>";
  }
  document.getElementById("overlay").classList.add("open");
}

