// ---- Canonical form for duplicate detection ----
function canon(url){
  let u = normUrl(url).toLowerCase();
  u = u.replace(/^https?:\/\//,"").replace(/^www\./,"").replace(/\/+$/,"").replace(/#.*$/,"");
  return u;
}
function findExisting(url, exceptId){
  const c = canon(url);
  return items.find(it => !it.loading && it.id!==exceptId && canon(it.url)===c);
}

// ---- Edit link (title, address, description) ----
let editId = null;
function openEdit(id){
  editId = id; const it = items.find(x=>x.id===id);
  document.getElementById("edTitle").value = it.title;
  document.getElementById("edUrl").value = it.url;
  document.getElementById("edDesc").value = it.desc;
  document.getElementById("edError").textContent = "";
  document.getElementById("editOverlay").classList.add("open");
  document.getElementById("edTitle").focus();
}
function closeEdit(){ document.getElementById("editOverlay").classList.remove("open"); editId=null; }
function saveEdit(){
  const it = items.find(x=>x.id===editId); if(!it) return;
  const title = document.getElementById("edTitle").value.trim();
  const url = document.getElementById("edUrl").value.trim();
  const desc = document.getElementById("edDesc").value.trim();
  const err = document.getElementById("edError");
  if(!url){ err.textContent = "An address is required."; return; }
  const clash = findExisting(url, it.id);
  if(clash){ err.textContent = "Another saved link already uses that address: “"+clash.title+"”."; return; }
  it.title = title || it.host; it.url = normUrl(url); it.host = hostOf(url); it.desc = desc;
  closeEdit(); render();
}
document.getElementById("editClose").addEventListener("click",closeEdit);
document.getElementById("editCancel").addEventListener("click",closeEdit);
document.getElementById("editSave").addEventListener("click",saveEdit);
document.getElementById("editOverlay").addEventListener("click",e=>{if(e.target.id==="editOverlay")closeEdit();});

// ---- Delete (with confirmation) ----
let deleteId = null;
function askDelete(id){
  deleteId = id; const it = items.find(x=>x.id===id);
  document.getElementById("cfMsg").innerHTML =
    "“<strong>"+it.title+"</strong>” and its saved copy, tags, and notes will be permanently removed. This cannot be undone.";
  document.getElementById("confirmOverlay").classList.add("open");
}
function closeConfirm(){ document.getElementById("confirmOverlay").classList.remove("open"); deleteId=null; }
document.getElementById("cfCancel").addEventListener("click",closeConfirm);
document.getElementById("cfOk").addEventListener("click",()=>{
  const i = items.findIndex(x=>x.id===deleteId); if(i>=0) items.splice(i,1);
  closeConfirm(); render();
});
document.getElementById("confirmOverlay").addEventListener("click",e=>{if(e.target.id==="confirmOverlay")closeConfirm();});

function flash(id){
  const li = document.querySelector('li.item [data-id="'+id+'"]');
  const card = li ? li.closest("li.item") : null;
  if(card){ card.classList.add("flash"); card.scrollIntoView({behavior:"smooth",block:"center"}); }
}

