function viewLabel(){
  let base = view==="toread" ? "the Reading list" : view==="archive" ? "the Archive" : "your Library";
  if (query.trim()) base = 'results for "'+query.trim()+'" in '+base;
  return base;
}
function updateSelectAll(){
  const el = document.getElementById("selectAll");
  const total = lastShownIds.length;
  const allSel = total>0 && lastShownIds.every(id=>selected.has(id));
  if (total===0){ el.innerHTML=""; return; }
  if (allSel){
    el.innerHTML = 'All '+total+' shown selected. <a id="selNone">Clear selection</a>';
    el.querySelector("#selNone").addEventListener("click",()=>{selected.clear();render();});
  } else {
    el.innerHTML = '<a id="selAll">Select all '+total+' in '+viewLabel()+'</a>';
    el.querySelector("#selAll").addEventListener("click",()=>{lastShownIds.forEach(id=>selected.add(id));render();});
  }
}
function updateBulk(){
  const bar = document.getElementById("bulkbar");
  const n = selected.size;
  if (n===0){ bar.classList.remove("show"); return; }
  bar.classList.add("show");
  document.getElementById("bulkCount").textContent = n + (n===1?" selected":" selected");
  document.getElementById("bulkScope").textContent = "· actions apply only to these "+n;
  document.getElementById("bulkArchive").textContent = view==="archive" ? "↩ Restore" : "🗄 Archive";
}

