// ---- Bulk actions (apply only to the current selection) ----
function selectedItems(){ return items.filter(it=>selected.has(it.id)); }
document.querySelectorAll("[data-bulk]").forEach(b=>b.addEventListener("click",()=>{
  const action = b.dataset.bulk;
  const sel = selectedItems();
  if (action==="clear"){ selected.clear(); render(); return; }
  if (sel.length===0) return;
  if (action==="toread"){ sel.forEach(it=>it.toRead=true); selected.clear(); render(); }
  else if (action==="read"){ sel.forEach(it=>it.toRead=false); selected.clear(); render(); }
  else if (action==="archive"){
    const restoring = view==="archive";
    sel.forEach(it=>it.archived=!restoring);
    selected.clear(); render();
  }
  else if (action==="tag"){
    const t = prompt("Add a tag to the "+sel.length+" selected link(s):");
    if (t && t.trim()){ const v=t.trim().toLowerCase(); sel.forEach(it=>{ if(!it.tags.includes(v)) it.tags.push(v); }); }
    selected.clear(); render();
  }
  else if (action==="delete"){ askBulkDelete(sel.length); }
}));

