let bulkDelete = false;
function askBulkDelete(n){
  bulkDelete = true;
  document.getElementById("cfMsg").innerHTML =
    "<strong>"+n+"</strong> selected link(s), with their saved copies, tags, and notes, will be permanently removed. This cannot be undone.";
  document.getElementById("confirmOverlay").classList.add("open");
}
function closeConfirm(){ document.getElementById("confirmOverlay").classList.remove("open"); deleteId=null; bulkDelete=false; }
document.getElementById("cfCancel").addEventListener("click",closeConfirm);
document.getElementById("cfOk").addEventListener("click",()=>{
  if (bulkDelete){
    const ids = new Set(selected);
    for (let i=items.length-1;i>=0;i--){ if(ids.has(items[i].id)) items.splice(i,1); }
    selected.clear();
  } else {
    const i = items.findIndex(x=>x.id===deleteId); if(i>=0) items.splice(i,1);
  }
  closeConfirm(); render();
});

