:root {
  --bg: #f7f8fa; --card: #ffffff; --ink: #1c2230; --muted: #6b7385;
  --line: #e4e7ee; --accent: #2f6df6; --accent-soft: #eaf1ff;
  --warn-bg: #fdecea; --warn-line: #f5c6c2; --warn-ink: #a3352b;
}
* { box-sizing: border-box; }
body { margin: 0; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: var(--bg); color: var(--ink); line-height: 1.5; }
header { background: var(--card); border-bottom: 1px solid var(--line);
  padding: 18px 28px; display: flex; align-items: center; gap: 12px; }
header h1 { font-size: 18px; margin: 0; font-weight: 650; }
main { max-width: 780px; margin: 0 auto; padding: 24px 20px 60px; }

.saver { background: var(--card); border: 1px solid var(--line); border-radius: 14px;
  padding: 18px 20px; margin-bottom: 22px; box-shadow: 0 1px 2px rgba(20,30,60,.04); }
.saver label { font-size: 13px; font-weight: 600; color: var(--muted); display: block; margin-bottom: 8px; }
.saver .row { display: flex; gap: 10px; }
.saver input { flex: 1; padding: 12px 14px; border: 1px solid var(--line); border-radius: 10px; font-size: 15px; outline: none; }
.saver input:focus { border-color: var(--accent); box-shadow: 0 0 0 3px var(--accent-soft); }
.saver button { padding: 12px 20px; border: none; background: var(--accent); color: #fff; font-size: 15px; font-weight: 600; border-radius: 10px; cursor: pointer; }
.saver button:hover { background: #2258d6; }

.tabs { display: flex; gap: 4px; margin-bottom: 16px; border-bottom: 1px solid var(--line); }
.tab { padding: 9px 16px; font-size: 14px; color: var(--muted); cursor: pointer; border: none; background: none; border-bottom: 2px solid transparent; font-weight: 600; }
.tab:hover { color: var(--ink); }
.tab.active { color: var(--accent); border-bottom-color: var(--accent); }
.tab .badge { font-size: 11px; background: var(--accent-soft); color: var(--accent); border-radius: 20px; padding: 1px 7px; margin-left: 6px; }

.toolbar { margin-bottom: 14px; display: flex; gap: 10px; align-items: center; }
.toolbar input[type=search] { flex: 1; padding: 11px 15px; border: 1px solid var(--line); border-radius: 10px; font-size: 15px; outline: none; background: var(--card); }
.toolbar input[type=search]:focus { border-color: var(--accent); box-shadow: 0 0 0 3px var(--accent-soft); }
.sortwrap { font-size: 13px; color: var(--muted); white-space: nowrap; }
.sortwrap select { font-size: 13px; padding: 8px 10px; border: 1px solid var(--line); border-radius: 8px; background: var(--card); margin-left: 4px; }

.notice { display: none; margin-bottom: 16px; padding: 11px 14px; border-radius: 10px; font-size: 14px; }
.notice.show { display: block; }
.notice.dup { background: #fff6e0; border: 1px solid #f0dca0; color: #7a5a1f; }
.notice.err { background: var(--warn-bg); border: 1px solid var(--warn-line); color: var(--warn-ink); }
.notice a { color: var(--accent); cursor: pointer; text-decoration: underline; }

.count { font-size: 13px; color: var(--muted); margin: 0 0 6px 2px; }
.selectall { font-size: 13px; color: var(--muted); margin: 0 0 12px 2px; min-height: 1px; }
.selectall a { color: var(--accent); cursor: pointer; text-decoration: underline; }

.bulkbar { display: none; align-items: center; gap: 8px; background: #1c2230; color: #fff; border-radius: 10px; padding: 10px 14px; margin-bottom: 14px; flex-wrap: wrap; position: sticky; top: 8px; z-index: 6; }
.bulkbar.show { display: flex; }
.bulkbar .bulkcount { font-weight: 700; font-size: 14px; }
.bulkbar .bulkscope { font-size: 12px; color: #b9c0d0; }
.bulkbar .spacer { flex: 1; }
.bulkbar .act { background: #2b3346; color: #e7ebf3; border-color: #3a4258; }
.bulkbar .act:hover { border-color: #6f8be0; color: #fff; }

ul.library { list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 12px; }
li.item { background: var(--card); border: 1px solid var(--line); border-radius: 12px; padding: 16px 18px; display: flex; gap: 12px; align-items: flex-start; position: relative; }
li.item.selected { border-color: var(--accent); box-shadow: 0 0 0 2px var(--accent-soft); }
li.item.flash { animation: flash 1.4s ease; }
@keyframes flash { 0%,100% { box-shadow: none; } 20%,60% { box-shadow: 0 0 0 3px var(--accent-soft); border-color: var(--accent); } }
.pick-cb { margin-top: 3px; width: 17px; height: 17px; flex-shrink: 0; cursor: pointer; }
.favicon { width: 38px; height: 38px; border-radius: 9px; background: var(--accent-soft); display: flex; align-items: center; justify-content: center; font-size: 17px; color: var(--accent); flex-shrink: 0; font-weight: 700; }
.body { flex: 1; min-width: 0; }
a.title { font-weight: 650; font-size: 16px; margin: 0 0 3px; display: inline-block; color: var(--ink); text-decoration: none; max-width: 100%; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; vertical-align: bottom; }
a.title:hover { color: var(--accent); text-decoration: underline; }
.flag { font-size: 11px; border-radius: 20px; padding: 2px 9px; margin-left: 6px; white-space: nowrap; }
.flag.toread { color: #c47d00; background: #fff6e0; border: 1px solid #f0dca0; }
.flag.copy { color: #2f7d4f; background: #e9f7ee; border: 1px solid #bfe6cd; }
.flag.copy.bad { color: var(--warn-ink); background: var(--warn-bg); border-color: var(--warn-line); }
.desc { font-size: 14px; color: #444b5c; margin: 2px 0 8px; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.warnstrip { font-size: 12px; color: var(--warn-ink); background: var(--warn-bg); border: 1px solid var(--warn-line); border-radius: 8px; padding: 7px 10px; margin: 4px 0 8px; display: flex; gap: 10px; align-items: center; }
.warnstrip button { font-size: 12px; border: 1px solid var(--warn-ink); color: var(--warn-ink); background: #fff; border-radius: 6px; padding: 2px 9px; cursor: pointer; }
.note-box { margin: 6px 0 8px; }
.note-text { font-size: 13px; color: #444b5c; background: #fffdf5; border: 1px solid #f0e6c8; border-left: 3px solid #e6c34d; border-radius: 8px; padding: 8px 11px; }
.note-text.clamped { display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.note-text p { margin: 0 0 6px; } .note-text p:last-child { margin: 0; }
.note-text h1,.note-text h2,.note-text h3 { font-size: 14px; margin: 4px 0; }
.note-text ul,.note-text ol { margin: 4px 0; padding-left: 20px; }
.note-text code { background: #f2edda; padding: 1px 4px; border-radius: 4px; }
.note-text a { color: var(--accent); }
.note-edit { width: 100%; font-size: 13px; padding: 8px 11px; border: 1px solid var(--accent); border-radius: 8px; outline: none; resize: vertical; min-height: 60px; font-family: inherit; }
.tags { display: flex; gap: 6px; flex-wrap: wrap; margin-bottom: 8px; align-items: center; }
.chip { font-size: 12px; color: var(--accent); background: var(--accent-soft); padding: 3px 10px; border-radius: 20px; display: inline-flex; align-items: center; gap: 5px; word-break: break-word; }
.chip .x { cursor: pointer; color: var(--muted); font-weight: 700; }
.chip .x:hover { color: #d23; }
.addtag { font-size: 12px; color: var(--muted); background: var(--bg); padding: 3px 10px; border-radius: 20px; border: 1px dashed var(--line); cursor: pointer; }
.addtag:hover { color: var(--accent); border-color: var(--accent); }
.meta { font-size: 12px; color: var(--muted); display: flex; gap: 10px; flex-wrap: wrap; }
.meta a { color: var(--muted); text-decoration: none; }
.meta a:hover { text-decoration: underline; }
.actions { display: flex; gap: 8px; margin-top: 10px; flex-wrap: wrap; }
.act { font-size: 12px; padding: 4px 11px; border-radius: 7px; cursor: pointer; border: 1px solid var(--line); background: var(--bg); color: var(--muted); }
.act:hover { border-color: var(--accent); color: var(--accent); }
.act.on { background: var(--accent-soft); border-color: var(--accent); color: var(--accent); }

.empty, .noresult { text-align: center; color: var(--muted); padding: 46px 20px; border: 1px dashed var(--line); border-radius: 14px; background: var(--card); }
.empty .big { font-size: 30px; margin-bottom: 8px; }
.empty .lead { font-size: 16px; color: var(--ink); font-weight: 600; margin-bottom: 4px; }
