.selectall a { color: var(--accent); cursor: pointer; text-decoration: underline; }

.bulkbar { display: none; align-items: center; gap: 8px; background: #1c2230; color: #fff; border-radius: 10px; padding: 10px 14px; margin-bottom: 14px; flex-wrap: wrap; position: sticky; top: 8px; z-index: 6; }
.bulkbar.show { display: flex; }
.bulkbar .bulkcount { font-weight: 700; font-size: 14px; }
.bulkbar .bulkscope { font-size: 12px; color: #b9c0d0; }
