.pick-cb { margin-top: 3px; width: 17px; height: 17px; flex-shrink: 0; cursor: pointer; }
.favicon { width: 38px; height: 38px; border-radius: 9px; background: var(--accent-soft); display: flex; align-items: center; justify-content: center; font-size: 17px; color: var(--accent); flex-shrink: 0; font-weight: 700; }
