.flag.toread { color: #c47d00; background: #fff6e0; border: 1px solid #f0dca0; }
.flag.copy { color: #2f7d4f; background: #e9f7ee; border: 1px solid #bfe6cd; }
.flag.copy.bad { color: var(--warn-ink); background: var(--warn-bg); border-color: var(--warn-line); }
.desc { font-size: 14px; color: #444b5c; margin: 2px 0 8px; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
