.addtag:hover { color: var(--accent); border-color: var(--accent); }
.meta { font-size: 12px; color: var(--muted); display: flex; gap: 10px; flex-wrap: wrap; }
.meta a { color: var(--muted); text-decoration: none; }
.meta a:hover { text-decoration: underline; }
.actions { display: flex; gap: 8px; margin-top: 10px; flex-wrap: wrap; }
.act { font-size: 12px; padding: 4px 11px; border-radius: 7px; cursor: pointer; border: 1px solid var(--line); background: var(--bg); color: var(--muted); }
.act:hover { border-color: var(--accent); color: var(--accent); }
.act.on { background: var(--accent-soft); border-color: var(--accent); color: var(--accent); }

.empty, .noresult { text-align: center; color: var(--muted); padding: 46px 20px; border: 1px dashed var(--line); border-radius: 14px; background: var(--card); }
.empty .big { font-size: 30px; margin-bottom: 8px; }
.empty .lead { font-size: 16px; color: var(--ink); font-weight: 600; margin-bottom: 4px; }
mark { background: #fff2ab; color: inherit; padding: 0 1px; border-radius: 2px; }

/* Popover (tag picker) */
.pop { position: absolute; z-index: 8; background: var(--card); border: 1px solid var(--line); border-radius: 12px; box-shadow: 0 8px 24px rgba(20,30,60,.14); padding: 12px; width: 250px; }
.pop .lbl { font-size: 11px; color: var(--muted); text-transform: uppercase; letter-spacing: .04em; margin: 0 0 8px; }
.pop .picklist { display: flex; gap: 6px; flex-wrap: wrap; margin-bottom: 10px; max-height: 160px; overflow: auto; }
.pop .pick { font-size: 12px; padding: 3px 10px; border-radius: 20px; cursor: pointer; border: 1px solid var(--line); background: var(--bg); color: var(--ink); }
.pop .pick.on { background: var(--accent); color: #fff; border-color: var(--accent); }
.pop input { width: 100%; font-size: 13px; padding: 7px 9px; border: 1px solid var(--line); border-radius: 8px; outline: none; }
.pop input:focus { border-color: var(--accent); }

/* Overlays / modals */
.overlay { position: fixed; inset: 0; background: rgba(20,30,60,.45); display: none; align-items: flex-start; justify-content: center; z-index: 20; padding: 40px 16px; overflow: auto; }
.overlay.open { display: flex; }
.modal { background: var(--card); border-radius: 14px; width: 100%; max-width: 560px; box-shadow: 0 20px 50px rgba(20,30,60,.3); }
.modal .head { padding: 16px 22px; border-bottom: 1px solid var(--line); display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.modal .head h3 { margin: 0; font-size: 16px; }
.modal .head .cap { font-size: 12px; color: #2f7d4f; background: #e9f7ee; border-radius: 20px; padding: 3px 10px; }
.modal .head .close { background: none; border: none; font-size: 22px; color: var(--muted); cursor: pointer; }
.modal .banner { background: #fbf7e6; border-bottom: 1px solid #f0e6c8; color: #7a6a2f; font-size: 12px; padding: 8px 22px; }
.modal .body { padding: 20px 22px; }
.snapframe { width: 100%; height: 60vh; border: 1px solid var(--line); border-radius: 8px; background: #fff; }
.fldlabel { font-size: 12px; font-weight: 600; color: var(--muted); display: block; margin: 14px 0 6px; }
.fld { width: 100%; padding: 10px 12px; border: 1px solid var(--line); border-radius: 9px; font-size: 14px; outline: none; font-family: inherit; }
.fld:focus { border-color: var(--accent); box-shadow: 0 0 0 3px var(--accent-soft); }
textarea.fld { min-height: 70px; resize: vertical; }
.fld-error { color: var(--warn-ink); font-size: 13px; margin-top: 10px; min-height: 1px; }
.btnrow { display: flex; gap: 10px; justify-content: flex-end; margin-top: 18px; }
.primary { padding: 9px 18px; border: none; background: var(--accent); color: #fff; font-size: 14px; font-weight: 600; border-radius: 9px; cursor: pointer; }
.primary:hover { background: #2258d6; }
.danger { padding: 9px 18px; border: none; background: #d23f31; color: #fff; font-size: 14px; font-weight: 600; border-radius: 9px; cursor: pointer; }
.danger:hover { background: #b12f24; }
</content>

